 JPanel destino=new JPanel(new FlowLayout(FlowLayout.LEFT,8,0));destino.setOpaque(false);destino.add(new JLabel("Proveedor:"));proveedores.setPreferredSize(new Dimension(235,34));destino.add(proveedores);destino.add(buscarProveedor);destino.add(nuevoProveedor);destino.add(new JLabel("Depósito:"));depositos.setPreferredSize(new Dimension(220,34));destino.add(depositos);documento.add(destino);norte.add(documento);norte.add(Box.createVerticalStrut(8));
 JPanel cards=new JPanel(new GridLayout(1,3,8,0));cards.setOpaque(false);cards.add(kpi("ARTÍCULOS DETECTADOS",detectados,BLUE));cards.add(kpi("VINCULADOS",vinculados,GREEN));cards.add(kpi("PENDIENTES DE REVISIÓN",pendientesLabel,new Color(166,91,12)));norte.add(cards);root.add(norte,BorderLayout.NORTH);
 JPanel centro=panel("PRODUCTOS DETECTADOS");centro.setLayout(new BorderLayout(6,6));tabla.setRowHeight(27);tabla.setFont(new Font("SansSerif",Font.PLAIN,13));tabla.setBackground(Color.WHITE);tabla.setForeground(INK);tabla.setSelectionBackground(new Color(210,229,250));tabla.setSelectionForeground(NAVY);tabla.setFillsViewportHeight(true);tabla.setAutoResizeMode(JTable.AUTO_RESIZE_OFF);tabla.getTableHeader().setPreferredSize(new Dimension(0,30));tabla.getTableHeader().setReorderingAllowed(false);
