 centro.add(new JScrollPane(tabla));JPanel tools=new JPanel(new FlowLayout(FlowLayout.LEFT,8,0));tools.setOpaque(false);tools.add(vincular);tools.add(alta);tools.add(new JLabel("Seleccioná una fila para vincular o corregir el producto."));centro.add(tools,BorderLayout.SOUTH);root.add(centro);
